cssVarsTemplate:
@tailwind base;
@tailwind components;
@tailwind utilities;

@layer base {
  :root {
    --background: 0 0% 100%;
    --foreground: 154 82.6% 10.9%;
    --card: 0 0% 100%;
    --card-foreground: 154 82.6% 10.9%;
    --popover: 0 0% 100%;
    --popover-foreground: 154 82.6% 10.9%;
    --primary: 154 83.3% 16.5%;
    --primary-foreground: 147 82.4% 96.3%;
    --secondary: 146 74.2% 92%;
    --secondary-foreground: 154 83.3% 16.5%;
    --muted: 146 74.2% 92%;
    --muted-foreground: 152 75.1% 39.4%;
    --accent: 146 74.2% 92%;
    --accent-foreground: 154 83.3% 16.5%;
    --destructive: 10 85% 58%;
    --destructive-foreground: 147 82.4% 96.3%;
    --border: 148 65.8% 80%;
    --input: 148 65.8% 80%;
    --ring: 154 82.6% 10.9%;
    --radius: 0.5rem;
    --chart-1: 12 76% 61%;
    --chart-2: 173 58% 39%;
    --chart-3: 197 37% 24%;
    --chart-4: 43 74% 66%;
    --chart-5: 27 87% 67%;
  }

  .dark {
    --background: 154 82.6% 10.9%;
    --foreground: 147 82.4% 96.3%;
    --card: 154 82.6% 10.9%;
    --card-foreground: 147 82.4% 96.3%;
    --popover: 154 82.6% 10.9%;
    --popover-foreground: 147 82.4% 96.3%;
    --primary: 147 82.4% 96.3%;
    --primary-foreground: 154 83.3% 16.5%;
    --secondary: 155 84.6% 19.8%;
    --secondary-foreground: 147 82.4% 96.3%;
    --muted: 155 84.6% 19.8%;
    --muted-foreground: 151 56.3% 54.1%;
    --accent: 155 84.6% 19.8%;
    --accent-foreground: 147 82.4% 96.3%;
    --destructive: 10 63% 29%;
    --destructive-foreground: 147 82.4% 96.3%;
    --border: 155 84.6% 19.8%;
    --input: 155 84.6% 19.8%;
    --ring: 150 63.2% 67%;
    --chart-1: 220 70% 50%;
    --chart-2: 160 60% 45%;
    --chart-3: 30 80% 55%;
    --chart-4: 280 65% 60%;
    --chart-5: 340 75% 55%;
  }
}

@layer base {
  * {
    @apply border-border;
  }
  body {
    @apply bg-background text-foreground;
  }
}
